27	func newTrailCmd() *cobra.Command {
28		var insecureHTTPAuth bool
29	
30		cmd := &cobra.Command{
31			Use:    "trail",
32			Short:  "Manage trails for your branches",
33			Hidden: true,
34			Long: `Trails are branch-centric work tracking abstractions. They describe the
35	"why" and "what" of your work, while checkpoints capture the "how" and "when".
36	
37	Running 'entire trail' without a subcommand shows the trail for the current
38	branch, or lists all trails if no trail exists for the current branch.`,
39			RunE: func(cmd *cobra.Command, _ []string) error {
