57	// trailInsecureHTTP reads the persistent --insecure-http-auth flag from the trail root command.
58	func trailInsecureHTTP(cmd *cobra.Command) bool {
59		v, _ := cmd.Flags().GetBool("insecure-http-auth") //nolint:errcheck // flag is always registered
60		return v
61	}
