63	// runTrailShow shows the trail for the current branch, or falls through to list.
64	func runTrailShow(ctx context.Context, w io.Writer, insecureHTTP bool) error {
65		branch, err := GetCurrentBranch(ctx)
66		if err != nil {
67			return runTrailListAll(ctx, w, "", false, false, insecureHTTP)
68		}
69	
70		client, err := NewAuthenticatedAPIClient(insecureHTTP)
71		if err != nil {
72			return fmt.Errorf("authentication required: %w", err)
73		}
74	
75		host, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
76		if err != nil {
77			return fmt.Errorf("failed to resolve repository: %w", err)
78		}
79	
80		found, err := findTrailByBranch(ctx, client, host, owner, repo, branch)
81		if err != nil {
82			return err
83		}
84		if found == nil {
85			return runTrailListAll(ctx, w, "", false, false, insecureHTTP)
86		}
87	
88		printTrailDetails(w, found.ToMetadata())
89		return nil
90	}
