92	func printTrailDetails(w io.Writer, m *trail.Metadata) {
93		fmt.Fprintf(w, "Trail: %s\n", m.Title)
94		fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
95		fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
96		fmt.Fprintf(w, "  Base:    %s\n", m.Base)
97		fmt.Fprintf(w, "  Status:  %s\n", m.Status)
98		fmt.Fprintf(w, "  Author:  %s\n", m.Author)
99		if m.Body != "" {
100			fmt.Fprintf(w, "  Body:    %s\n", m.Body)
101		}
102		if len(m.Labels) > 0 {
103			fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
104		}
105		if len(m.Assignees) > 0 {
106			fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
107		}
108		fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
109		fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
110	}
