132	func runTrailListAll(ctx context.Context, w io.Writer, statusFilter string, jsonOutput, showAll, insecureHTTP bool) error {
133		client, err := NewAuthenticatedAPIClient(insecureHTTP)
134		if err != nil {
135			return fmt.Errorf("authentication required: %w", err)
136		}
137	
138		host, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
139		if err != nil {
140			return fmt.Errorf("failed to resolve repository: %w", err)
141		}
142	
143		resp, err := client.Get(ctx, trailsBasePath(host, owner, repo))
144		if err != nil {
145			return fmt.Errorf("failed to list trails: %w", err)
146		}
147		defer resp.Body.Close()
148		if err := checkTrailResponse(resp); err != nil {
149			return err
150		}
151	
152		var listResp api.TrailListResponse
153		if err := api.DecodeJSON(resp, &listResp); err != nil {
154			return fmt.Errorf("failed to decode trail list: %w", err)
155		}
156	
157		// Convert to metadata for display
158		trails := make([]*trail.Metadata, 0, len(listResp.Trails))
159		for i := range listResp.Trails {
160			trails = append(trails, listResp.Trails[i].ToMetadata())
161		}
162	
163		totalCount := len(trails)
164	
165		// Apply status filter
166		if statusFilter != "" {
167			status := trail.Status(statusFilter)
168			if !status.IsValid() {
169				return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
170			}
171			var filtered []*trail.Metadata
172			for _, t := range trails {
173				if t.Status == status {
174					filtered = append(filtered, t)
175				}
176			}
177			trails = filtered
178		} else if !showAll {
179			// By default, hide merged and closed trails
180			var filtered []*trail.Metadata
181			for _, t := range trails {
182				if t.Status != trail.StatusMerged && t.Status != trail.StatusClosed {
183					filtered = append(filtered, t)
184				}
185			}
186			trails = filtered
187		}
188	
189		// Sort by updated_at descending
190		sort.Slice(trails, func(i, j int) bool {
191			return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
192		})
193	
194		if jsonOutput {
195			enc := json.NewEncoder(w)
196			enc.SetIndent("", "  ")
197			if err := enc.Encode(trails); err != nil {
198				return fmt.Errorf("failed to encode JSON: %w", err)
199			}
200			return nil
201		}
202	
203		if len(trails) == 0 {
204			hiddenCount := totalCount - len(trails)
205			if hiddenCount > 0 {
206				fmt.Fprintf(w, "No active trails found. %d merged/closed trail(s) hidden — use --all to show.\n", hiddenCount)
207			} else {
208				fmt.Fprintln(w, "No trails found.")
209				fmt.Fprintln(w)
210				fmt.Fprintln(w, "Commands:")
211				fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
212				fmt.Fprintln(w, "  entire trail list     List all trails")
213				fmt.Fprintln(w, "  entire trail update   Update trail metadata")
214			}
215			return nil
216		}
217	
218		// Table output
219		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
220		for _, t := range trails {
221			branch := stringutil.TruncateRunes(t.Branch, 30, "...")
222			title := stringutil.TruncateRunes(t.Title, 40, "...")
223			fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
224				branch, title, t.Status, stringutil.TruncateRunes(t.Author, 15, "..."), timeAgo(t.UpdatedAt))
225		}
226	
227		return nil
228	}
