252	//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
253	func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
254		ctx := cmd.Context()
255		w := cmd.OutOrStdout()
256		errW := cmd.ErrOrStderr()
257	
258		// --- Phase 1: Local git operations (no API calls) ---
259	
260		repo, err := strategy.OpenRepository(ctx)
261		if err != nil {
262			return fmt.Errorf("failed to open repository: %w", err)
263		}
264	
265		// Determine base branch
266		if base == "" {
267			base = strategy.GetDefaultBranchName(repo)
268			if base == "" {
269				base = defaultBaseBranch
270			}
271		}
272	
273		_, currentBranch, _ := IsOnDefaultBranch(ctx) //nolint:errcheck // best-effort detection
274		interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
275	
276		if interactive {
277			// Interactive flow: title → body → branch (derived) → status
278			if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
279				return handleFormCancellation(w, "Trail creation", err)
280			}
281		} else {
282			// Non-interactive: derive missing values from provided flags
283			if branch == "" {
284				if cmd.Flags().Changed("title") {
285					branch = slugifyTitle(title)
286				} else {
287					branch = currentBranch
288				}
289			}
290			if title == "" {
291				title = trail.HumanizeBranchName(branch)
292			}
293		}
294		if branch == "" {
295			return errors.New("branch name is required")
296		}
297	
298		// Create the local branch if it doesn't exist
299		needsCreation := branchNeedsCreation(repo, branch)
300		if needsCreation {
301			if err := createBranch(repo, branch); err != nil {
302				return fmt.Errorf("failed to create branch %q: %w", branch, err)
303			}
304			fmt.Fprintf(w, "Created branch %s\n", branch)
305		} else if currentBranch != branch {
306			fmt.Fprintf(w, "Note: trail will be created for branch %q (not the current branch)\n", branch)
307		}
308	
309		// Push the branch so the API can reference it
310		if needsCreation {
311			if err := pushBranchToOrigin(branch); err != nil {
312				fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
313			} else {
314				fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
315			}
316		}
317	
318		// --- Phase 2: API operations ---
319	
320		client, err := NewAuthenticatedAPIClient(trailInsecureHTTP(cmd))
321		if err != nil {
322			return fmt.Errorf("authentication required: %w", err)
323		}
324	
325		host, owner, repoName, err := gitremote.ResolveRemoteRepo(ctx, "origin")
326		if err != nil {
327			return fmt.Errorf("failed to resolve repository: %w", err)
328		}
329	
330		createReq := api.TrailCreateRequest{
331			Title:      title,
332			Body:       body,
333			BranchName: branch,
334			Base:       base,
335			Status:     statusStr,
336		}
337	
338		resp, err := client.Post(ctx, trailsBasePath(host, owner, repoName), createReq)
339		if err != nil {
340			return fmt.Errorf("failed to create trail: %w", err)
341		}
342		defer resp.Body.Close()
343		if err := checkTrailResponse(resp); err != nil {
344			return err
345		}
346	
347		var createResp api.TrailCreateResponse
348		if err := api.DecodeJSON(resp, &createResp); err != nil {
349			return fmt.Errorf("failed to decode create response: %w", err)
350		}
351	
352		fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", createResp.Trail.Title, createResp.Trail.Branch, createResp.Trail.TrailID)
353	
354		// --- Phase 3: Post-creation local operations ---
355	
356		if needsCreation && currentBranch != branch {
357			shouldCheckout := checkout
358			if !shouldCheckout && !cmd.Flags().Changed("checkout") {
359				// Interactive: ask whether to checkout
360				form := NewAccessibleForm(
361					huh.NewGroup(
362						huh.NewConfirm().
363							Title(fmt.Sprintf("Check out branch %s?", branch)).
364							Value(&shouldCheckout),
365					),
366				)
367				if formErr := form.Run(); formErr == nil && shouldCheckout {
368					checkout = true
369				}
370			}
371			if checkout {
372				if err := CheckoutBranch(ctx, branch); err != nil {
373					return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
374				}
375				fmt.Fprintf(w, "Switched to branch %s\n", branch)
376			}
377		}
378	
379		return nil
380	}
