502	// buildTrailUpdateRequest constructs a PATCH request body from the current trail and the requested changes.
503	func buildTrailUpdateRequest(current *api.TrailResource, statusStr, title, body string, labelAdd, labelRemove []string) api.TrailUpdateRequest {
504		var req api.TrailUpdateRequest
505	
506		if statusStr != "" {
507			req.Status = &statusStr
508		}
509		if title != "" {
510			req.Title = &title
511		}
512		if body != "" {
513			req.Body = &body
514		}
515	
516		// Handle label changes: merge adds, remove removes
517		if len(labelAdd) > 0 || len(labelRemove) > 0 {
518			labels := make([]string, 0, len(current.Labels)+len(labelAdd))
519			labels = append(labels, current.Labels...)
520			for _, l := range labelAdd {
521				found := false
522				for _, existing := range labels {
523					if existing == l {
524						found = true
525						break
526					}
527				}
528				if !found {
529					labels = append(labels, l)
530				}
531			}
532			for _, l := range labelRemove {
533				for i, existing := range labels {
534					if existing == l {
535						labels = append(labels[:i], labels[i+1:]...)
536						break
537					}
538				}
539			}
540			req.Labels = &labels
541		}
542	
543		return req
544	}
