558	// runTrailCreateInteractive runs the interactive form for trail creation.
559	// Prompts for title, body, branch (derived from title), and status.
560	func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
561		// Step 1: Title and body
562		form := NewAccessibleForm(
563			huh.NewGroup(
564				huh.NewInput().
565					Title("Trail title").
566					Placeholder("What are you working on?").
567					Value(title),
568				huh.NewText().
569					Title("Body (optional)").
570					Value(body),
571			),
572		)
573		if err := form.Run(); err != nil {
574			return fmt.Errorf("form cancelled: %w", err)
575		}
576		*title = strings.TrimSpace(*title)
577		if *title == "" {
578			return errors.New("trail title is required")
579		}
580	
581		// Step 2: Branch (derived from title) and status
582		suggested := slugifyTitle(*title)
583		*branch = suggested
584	
585		// Build status options, excluding done/closed
586		var statusOptions []huh.Option[string]
587		for _, s := range trail.ValidStatuses() {
588			if s == trail.StatusMerged || s == trail.StatusClosed {
589				continue
590			}
591			statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
592		}
593		if *statusStr == "" {
594			*statusStr = string(trail.StatusDraft)
595		}
596	
597		form = NewAccessibleForm(
598			huh.NewGroup(
599				huh.NewInput().
600					Title("Branch name").
601					Placeholder(suggested).
602					Value(branch),
603				huh.NewSelect[string]().
604					Title("Status").
605					Options(statusOptions...).
606					Value(statusStr),
607			),
608		)
609		if err := form.Run(); err != nil {
610			return fmt.Errorf("form cancelled: %w", err)
611		}
612		*branch = strings.TrimSpace(*branch)
613		if *branch == "" {
614			*branch = suggested
615		}
616		return nil
617	}
618	
619	// findTrailByBranch looks up a trail by branch name via the list API.
620	func findTrailByBranch(ctx context.Context, client *api.Client, host, owner, repo, branch string) (*api.TrailResource, error) {
621		resp, err := client.Get(ctx, trailsBasePath(host, owner, repo))
622		if err != nil {
623			return nil, fmt.Errorf("list trails: %w", err)
624		}
625		defer resp.Body.Close()
626		if err := checkTrailResponse(resp); err != nil {
627			return nil, err
628		}
629	
630		var listResp api.TrailListResponse
631		if err := api.DecodeJSON(resp, &listResp); err != nil {
632			return nil, fmt.Errorf("decode trail list: %w", err)
633		}
634	
635		for i := range listResp.Trails {
636			if listResp.Trails[i].Branch == branch {
637				return &listResp.Trails[i], nil
638			}
639		}
640		return nil, nil //nolint:nilnil // nil, nil means "not found" — callers check both
641	}
642	
643	// apiHostAlias maps git host domains to short aliases used by the trails API.
644	var apiHostAlias = map[string]string{
645		"github.com": "gh",
646	}
647	
648	// trailsBasePath returns the API path prefix for trails endpoints (e.g., "/api/v1/trails/gh/org/repo").
649	func trailsBasePath(host, owner, repo string) string {
650		if alias, ok := apiHostAlias[host]; ok {
651			host = alias
652		}
653		return fmt.Sprintf("/api/v1/trails/%s/%s/%s", host, owner, repo)
654	}
655	
656	// checkTrailResponse checks the API response and returns user-friendly errors.
657	// For auth failures, it appends a hint to re-authenticate while preserving the server's error message.
658	func checkTrailResponse(resp *http.Response) error {
659		if err := api.CheckResponse(resp); err != nil {
660			if resp.StatusCode == http.StatusUnauthorized || resp.StatusCode == http.StatusForbidden {
661				return fmt.Errorf("%w — run 'entire login' to re-authenticate", err)
662			}
663			return fmt.Errorf("trail API: %w", err)
664		}
665		return nil
666	}
667	
668	// slugifyTitle converts a title string into a branch-friendly slug.
669	// Example: "Add user authentication" -> "add-user-authentication"
670	func slugifyTitle(title string) string {
671		s := strings.ToLower(strings.TrimSpace(title))
672		// Replace spaces and underscores with hyphens
673		s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
674		// Remove anything that's not alphanumeric, hyphen, or slash
675		var b strings.Builder
676		prevHyphen := false
677		for _, r := range s {
678			if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
679				b.WriteRune(r)
680				prevHyphen = false
681			} else if r == '-' && !prevHyphen {
682				b.WriteRune('-')
683				prevHyphen = true
684			}
685		}
686		return strings.Trim(b.String(), "-")
687	}
688	
689	// branchNeedsCreation checks if a branch exists locally.
690	func branchNeedsCreation(repo *git.Repository, branchName string) bool {
691		_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
692		return err != nil
693	}
694	
695	// createBranch creates a new local branch pointing at HEAD without checking it out.
696	func createBranch(repo *git.Repository, branchName string) error {
697		head, err := repo.Head()
698		if err != nil {
699			return fmt.Errorf("failed to get HEAD: %w", err)
700		}
701		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
702		if err := repo.Storer.SetReference(ref); err != nil {
703			return fmt.Errorf("failed to create branch ref: %w", err)
704		}
705		return nil
706	}
707	
708	// pushBranchToOrigin pushes a branch to the origin remote.
709	func pushBranchToOrigin(branchName string) error {
710		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
711		defer cancel()
712		cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
713		if output, err := cmd.CombinedOutput(); err != nil {
714			return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
715		}
716		return nil
717	}
718

